// Simple in-process store for the demo. In a real app this would be a database.
// Module-level state persists across Server Action invocations and
// revalidations within the same running server process.

export type NotificationPreference = {
  notificationsEnabled: boolean;
};

let preference: NotificationPreference = {
  notificationsEnabled: false,
};

export function getNotificationPreference(): NotificationPreference {
  return { ...preference };
}

export function setNotificationPreference(
  next: NotificationPreference,
): void {
  preference = { ...next };
}

