'use server';

import { revalidatePath } from 'next/cache';

import {
  getNotificationPreference,
  setNotificationPreference,
} from './lib/preferences';

/**
 * Toggles the signed-in user's notification preference between on and off.
 *
 * After mutating the underlying data, we call `revalidatePath` with the
 * current page path. This is Next.js's recommended way to refresh the
 * current page's data from within a Server Action: it purges the router
 * cache for that path so the Server Component re-renders with the updated
 * preference, without issuing a redirect or a full page navigation.
 */
export async function toggleNotifications(): Promise<void> {
  const current = getNotificationPreference();
  setNotificationPreference({
    notificationsEnabled: !current.notificationsEnabled,
  });

  // Refresh the current page's cached data so it reflects the new state.
  revalidatePath('/');
}

