import { getNotificationPreference } from './lib/preferences';
import { toggleNotifications } from './actions';

export default async function Home() {
  const { notificationsEnabled } = getNotificationPreference();

  return (
    <main>
      <h1>Settings</h1>

      <section>
        <h2>Notifications</h2>
        <p>
          Current preference:{' '}
          <strong>{notificationsEnabled ? 'On' : 'Off'}</strong>
        </p>

        <form action={toggleNotifications}>
          <button type="submit">
            {notificationsEnabled ? 'Turn notifications off' : 'Turn notifications on'}
          </button>
        </form>
      </section>
    </main>
  );
}

